insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('cannabis-anbau-grundlagen', 'Cannabis-Anbau: Die wissenschaftlichen Grundlagen', 'Wie Licht, Klima und Naehrstoffe zusammenspielen und warum Wiederholbarkeit wichtiger ist als Hype-Tricks.', '[{"type":"definition","heading":"Systemdenken statt Einzeltricks","content":["Ertrag und Qualitaet entstehen aus stabilen Prozessen — nicht aus isolierten Tricks.","Licht, Klima und Naehrstoffe greifen ineinander: eine Aenderung beeinflusst immer das Gesamtsystem."],"checklist":["VPD-Zielbereich pro Wachstumsphase definieren","Messpunkte fuer Klima festlegen (Canopy, Raum, Zu-/Abluft)","Wochenreview mit Ertrag, Qualitaet und Problemen"]},{"type":"definition","heading":"Warum das deinen Ertrag und deine Qualitaet direkt beeinflusst","content":["Instabile Parameter erzeugen Stress. Stress kostet Ertrag und verschlechtert das Terpenprofil.","Wer Messwerte nicht dokumentiert, kann Ursachen nach einem schlechten Run nicht zurueckverfolgen."]},{"type":"definition","heading":"Datensaubere Routinen","content":["Notiere Futterstaerke, pH-Korrekturen und Giesstermine in einer einheitlichen Struktur.","Nur so lassen sich Ursache-Wirkung-Beziehungen spaeter sicher bewerten."]},{"type":"definition","heading":"In SecretLeaf relevant wenn","content":["du deinen ersten Run startest und kein Setup-Protokoll hast","Qualitaet oder Ertrag zwischen Runs schwankt, ohne erkennbaren Grund","du eine Variable (Licht, Duenger, Temperatur) anpassen willst und die Auswirkung verstehen moechtest"]},{"type":"definition","heading":"Was du konkret tun solltest","content":[],"checklist":["Lege heute fixe Messpunkte fest: Temperatur, RH, pH, EC — taegliche zur gleichen Zeit","Schreibe jede Aenderung mit Datum ins Grow-Log, bevor du sie machst","Aendere nur eine Variable pro Woche — sonst kannst du Ursachen nicht isolieren"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'anbau'), 'foundational'::knowledge_difficulty, 'published'::knowledge_status, 9, 5, 'Wie Licht, Klima und Naehrstoffe zusammenspielen und warum Wiederholbarkeit wichtiger ist als Hype-Tricks.', 'de', '2026-03-26'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('vpd-einfach-erklaert', 'VPD einfach erklaert', 'Was das Dampfdruckdefizit bedeutet und wie es Wachstum, Transpiration und Schimmelrisiko steuert.', '[{"type":"definition","heading":"Warum VPD praktischer als RH allein ist","content":["Relative Luftfeuchte ohne Temperaturkontext fuehrt oft zu Fehlentscheidungen.","VPD verbindet Temperatur und Feuchte in einer direkt handlungsorientierten Kennzahl."]},{"type":"definition","heading":"Praxisleitfaden","content":["Arbeite mit Phase-Profilen (Jungpflanze, Wachstum, Bluete) und teste nur kleine Aenderungen.","Nach jeder Korrektur mindestens 24 Stunden beobachten, bevor erneut eingegriffen wird."],"checklist":["Sensor-Kalibrierung monatlich pruefen","Blatttemperatur per IR-Messung einbeziehen","Warnschwellen fuer zu trockene/zu feuchte Luft definieren"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'werkzeuge'), 'foundational'::knowledge_difficulty, 'published'::knowledge_status, 6, 5, 'Was das Dampfdruckdefizit bedeutet und wie es Wachstum, Transpiration und Schimmelrisiko steuert.', 'de', '2026-03-26'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('wasseraktivitaet-und-curing', 'Wasseraktivitaet und Curing', 'Warum aw-Werte fuer Stabilitaet, Aromaerhalt und mikrobiologische Sicherheit entscheidend sind.', '[{"type":"definition","heading":"Nachernte als Qualitaetshebel","content":["Curing ist kein kosmetischer Schritt, sondern ein kritischer Teil des Qualitaetsmanagements.","Ein fehlerhafter Ablauf kann zuvor gute Ernten stark entwerten."]},{"type":"definition","heading":"Operative Umsetzung","content":["Arbeite mit fixen Messintervallen, Chargenkennzeichnung und klaren Grenzwerten fuer Nachjustierungen.","Dokumentiere Auffaelligkeiten frueh, um spaetere Reklamationen nachvollziehen zu koennen."],"checklist":["Charge eindeutig labeln","aw und Temperatur protokollieren","Abweichungen mit Korrekturmassnahme verknuepfen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'qualitaet'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 8, 5, 'Warum aw-Werte fuer Stabilitaet, Aromaerhalt und mikrobiologische Sicherheit entscheidend sind.', 'de', '2026-03-26'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('vpd-und-ec-kombi-rechner-guide', 'VPD- und EC-Leitfaden', 'Wie Klima- und Naehrstoffsteuerung gemeinsam optimiert werden, statt isolierte Einzelwerte zu verfolgen.', '[{"type":"definition","heading":"Regelstrategie aufbauen","content":["Definiere Prioritaeten: zuerst Klimastabilitaet, dann Naehrstofffeinsteuerung.","Nutze Trenddaten statt Einzelmesspunkte fuer Entscheidungen."]},{"type":"definition","heading":"Monitoring und Alarmierung","content":["Lege harte Alert-Level fuer VPD-Drift, EC-Ausreisser und Temperaturspruenge fest.","Verknuepfe jeden Alarm mit klarer Reaktionsanweisung fuer das Team."],"checklist":["Alarmmatrix dokumentiert","Eskalationsverantwortliche benannt","Monatliche Ueberpruefung der Schwellenwerte"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'werkzeuge'), 'advanced'::knowledge_difficulty, 'published'::knowledge_status, 10, 5, 'Wie Klima- und Naehrstoffsteuerung gemeinsam optimiert werden, statt isolierte Einzelwerte zu verfolgen.', 'de', '2026-03-26'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('cannabis-substrat-und-wurzelzone', 'Substrat und Wurzelzone verstehen', 'Wie Luftporen, Wasserhaltekapazitaet und Wurzelgesundheit die Stabilitaet eines Grows bestimmen.', '[{"type":"definition","heading":"Warum die Wurzelzone wichtiger ist als der letzte Booster","content":["Pflanzen reagieren zuerst auf Bedingungen im Wurzelraum. Wenn Sauerstoff, Feuchte und Temperatur instabil sind, hilft auch perfekte Blattduengung nur begrenzt.","Ein reproduzierbares System beginnt deshalb unten: Medium, Topfvolumen, Drain und Giessrhythmus muessen zusammenpassen."]},{"type":"definition","heading":"Welche Checks im Alltag wirklich helfen","content":["Arbeite mit Topfgewicht, Substratbeobachtung und Drain-Messung statt nur nach Gefuehl. So erkennst du Staunaesse und Unterversorgung frueh.","Halte Temperatur und Trocknungsdauer pro Charge oder Zone fest, damit spaetere Probleme klar zugeordnet werden koennen."],"checklist":["Topfgewicht nass und trocken dokumentieren","Drain-EC und Drain-pH woechentlich messen","Wurzelraum vor Hitze und Kaltespitzen schuetzen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'anbau'), 'foundational'::knowledge_difficulty, 'published'::knowledge_status, 7, 5, 'Wie Luftporen, Wasserhaltekapazitaet und Wurzelgesundheit die Stabilitaet eines Grows bestimmen.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('bewaesserung-ohne-uebergiessen', 'Bewaesserung ohne Uebergiessen', 'Wie Giessmenge, Intervall und Drain so abgestimmt werden, dass Pflanzen weder austrocknen noch ersticken.', '[{"type":"definition","heading":"Warum Uebergiessen so haeufig passiert","content":["Viele Teams reagieren auf haengende Blaetter reflexartig mit mehr Wasser. Dabei koennen dieselben Symptome auch von Sauerstoffmangel im Medium kommen.","Ein sauberer Bewaesserungsplan basiert daher auf Messpunkten und nicht auf spontaner Interpretation einzelner Pflanzen."]},{"type":"definition","heading":"Ein belastbarer Giessprozess","content":["Lege je Medium ein Zielgewicht, typische Trocknungsdauer und Minimal-Drain fest. So lassen sich Abweichungen frueh erkennen.","Wenn Klima und VPD schwanken, muss auch die Wassergabe angepasst werden. Der Rhythmus ist kein statischer Wochenplan."],"checklist":["Vor jedem Giessen Topfgewicht vergleichen","Drain nur in definierten Kontrollgiessungen messen","Abweichungen im Grow-Log mit Klimaereignissen koppeln"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'anbau'), 'foundational'::knowledge_difficulty, 'published'::knowledge_status, 6, 5, 'Wie Giessmenge, Intervall und Drain so abgestimmt werden, dass Pflanzen weder austrocknen noch ersticken.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('lichtstress-und-canopy-management', 'Lichtstress und Canopy-Management', 'Wie Lichtverteilung, Abstand und Blattflaeche zusammenwirken und wann hohe Intensitaet mehr schadet als hilft.', '[{"type":"definition","heading":"Warum Licht immer ein Systemparameter ist","content":["Hohe Lichtleistung steigert nur dann Leistung, wenn Transpiration, Wasserhaushalt und Temperatur sauber gefuehrt werden.","Wird Licht isoliert hochgezogen, entstehen oft Stresssymptome statt echter Mehrleistung."]},{"type":"definition","heading":"Canopy sauber fuehren","content":["Trainiere Pflanzen so, dass die obere Blattflaeche moeglichst gleichmaessig bleibt. Dadurch werden Hotspots und Schatteninseln reduziert.","Mappe die Lichtverteilung im Raum und passe Lampenhoehe oder Pflanzenerziehung datenbasiert an."],"checklist":["PPFD an mehreren Rasterpunkten messen","Blatttemperatur an Hotspots pruefen","Canopy-Hoehe pro Zone dokumentieren"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'anbau'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 8, 5, 'Wie Lichtverteilung, Abstand und Blattflaeche zusammenwirken und wann hohe Intensitaet mehr schadet als hilft.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('schimmel-und-mykotoxine-bei-cannabis', 'Schimmel und Mykotoxine bei Cannabis', 'Warum mikrobiologische Sicherheit nicht an der sichtbaren Bluete endet und welche Informationsluecken besonders riskant sind.', '[{"type":"definition","heading":"Warum Sichtkontrolle nicht reicht","content":["Schimmel oder toxinbezogene Risiken koennen bereits relevant sein, ohne dass ein Produkt fuer Laien eindeutig auffaellig aussieht.","Deshalb sind Laborwerte und Prozesshistorie fuer serioese Bewertung unverzichtbar."]},{"type":"definition","heading":"Wo Praevention ansetzt","content":["Kontrollierte Trocknung, stabile Lagerung und klare Sperrlogik reduzieren das Risiko deutlich. Gleichzeitig muessen Hinweise fuer Teams praktisch umsetzbar bleiben.","Gerade nach der Ernte ist saubere Prozessfuehrung entscheidend."],"checklist":["aw und Temperatur im Nachernteprozess dokumentieren","Auffaellige Chargen sofort sperren","Mikrobiologische Daten nicht isoliert lesen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'sicherheit'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 8, 5, 'Warum mikrobiologische Sicherheit nicht an der sichtbaren Bluete endet und welche Informationsluecken besonders riskant sind.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('grow-log-und-kpi-dashboard', 'Grow-Log und KPI-Dashboard aufbauen', 'Welche Kennzahlen fuer Wiederholbarkeit wirklich helfen und wie aus Beobachtung ein steuerbares System wird.', '[{"type":"definition","heading":"Welche Daten wirklich helfen","content":["Nicht alles muss gemessen werden. Entscheidend sind Klima, Bewaesserung, Naehrstoffdaten, Auffaelligkeiten und Outcome-Kennzahlen.","Aus diesen Daten entsteht ein lernendes System, wenn sie ueber Runs vergleichbar bleiben."]},{"type":"definition","heading":"Vom Log zur Steuerung","content":["Kennzahlen muessen sichtbar machen, wann eingegriffen wird und wer entscheidet. Erst dann wird ein Dashboard operativ wertvoll.","Gerade fuer Teams verhindert das Datenblindheit und Einzelheldentum."],"checklist":["Kern-KPIs pro Phase definieren","Trendansicht statt reiner Tabellen pflegen","Jede KPI mit Reaktionslogik verknuepfen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'werkzeuge'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 8, 5, 'Welche Kennzahlen fuer Wiederholbarkeit wirklich helfen und wie aus Beobachtung ein steuerbares System wird.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('sensor-kalibrierung-und-messfehler', 'Sensor-Kalibrierung und Messfehler', 'Warum selbst gute Tools ohne Kalibrierung in die Irre fuehren und wie Messqualitaet systematisch abgesichert wird.', '[{"type":"definition","heading":"Warum gute Sensoren alleine nicht reichen","content":["Auch hochwertige Geraete koennen falsch messen, wenn sie schlecht platziert, lange ungeprueft oder falsch gelesen werden.","Gerade in Grow- und Lagerumgebungen summieren sich kleine Messfehler schnell."]},{"type":"definition","heading":"Wie ein einfacher QA-Prozess aussieht","content":["Definiere Kalibrierintervalle, Vergleichsmessungen und dokumentierte Austauschregeln. So wird aus Sensorik ein belastbares Werkzeug.","Ohne diese Ebene bleiben VPD-, pH- oder EC-Werte schnell trügerisch."],"checklist":["Kalibrierintervall pro Sensortyp festlegen","Referenzmessungen dokumentieren","Auffaellige Sensoren sofort markieren oder tauschen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'werkzeuge'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 7, 5, 'Warum selbst gute Tools ohne Kalibrierung in die Irre fuehren und wie Messqualitaet systematisch abgesichert wird.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('how-to-grow-cannabis-anfaenger-tutorial', 'How to Grow Cannabis: Schritt-fuer-Schritt fuer Anfaenger', 'Ein klarer Einstieg in Setup, Klima, Bewaesserung und Erntefenster - aufgebaut auf belastbaren Grundlagen aus Forschung und bewaehrten Profi-Routinen.', '[{"type":"definition","heading":"Schritt 1: Setup klein und reproduzierbar halten","content":["Waehle ein ueberschaubares Setup mit klar kontrollierbaren Variablen: Licht, Abluft, Umluft, Temperatur, RH und ein einfaches Substrat. Forschung zu Cannabis-Kultivierung und professionelle Grow-SOPs zeigen uebereinstimmend, dass Stabilitaet den groessten Hebel hat.","Fuer den Einstieg ist ein verzeihendes Medium mit dokumentierbarem Giessrhythmus wichtiger als ein aggressives High-Performance-System. Erde oder ein gut vorbereiteter Mix mit klarer Trocknungsdynamik ist meist einfacher als sofortige Hydro-Steuerung."],"checklist":["Lichtleistung konservativ starten und Hoehe dokumentieren","Temperatur und RH am Canopy messen","Substrat, Topfvolumen und Ziel-Giessrhythmus vor dem Start festlegen"]},{"type":"environmental_factors","heading":"Schritt 2: Klima und Bewaesserung zuerst stabilisieren","content":["Halte in der Vegetationsphase keine extremen Werte, sondern stabile Korridore. VPD-orientiertes Arbeiten und regelmaessige Topfgewicht-Kontrolle sind fuer Anfaenger deutlich wertvoller als hektische EC-Optimierung.","Viele Probleme im ersten Run entstehen durch zu haeufiges Giessen und zu viele Korrekturen gleichzeitig. Arbeite mit einem festen Beobachtungsfenster: Blaetter, Topfgewicht, Drain, Temperatur und Luftfeuchte."],"checklist":["Vor jedem Giessen Topfgewicht oder Trocknungsgrad pruefen","Nur einen Parameter pro Tag aendern","Klimaabweichungen mit Datum und Uhrzeit ins Grow-Log schreiben"]},{"type":"definition","heading":"Schritt 2b: Wochenplan fuer einen einfachen ersten Run","content":["Woche 1-2: Keimung und Jungpflanze. Licht moderat halten, RH hoeher fahren, Medium nur leicht feucht und keine harten Duengeimpulse setzen. Fokus: stabile Entwicklung statt Tempo.","Woche 3-4: Fruehe Vegetation. Gleichmaessigen Rhythmus aus Giessen, Klima-Check und leichter Naehrstoffzufuhr etablieren. Jetzt zeigt sich, ob Topf, Medium und Trocknungsdauer zusammenpassen.","Woche 5-6: Spaete Vegetation bis Stretch. Pflanzenhoehe, Lichtabstand und Blattgesundheit eng beobachten. Nur dann auf Bluete umstellen, wenn Pflanzen vital und der Raum klimatisch stabil ist.","Woche 7-9: Hauptbluete. Stickstoff nicht aggressiv pushen, Giessrhythmus eng fuehren und Klima trocken genug halten, damit keine dichten, feuchten Problemzonen entstehen.","Woche 10+: Reife, Ernte und Trocknung. Trichome beobachten, letzte grobe Korrekturen vermeiden und Trocknungsraum vor dem Schnitt komplett vorbereiten."],"checklist":["Jede Woche nur ein klares Lernziel definieren","Vor der Bluete kein ungelostes Giess- oder Klima-Problem mitnehmen","Trocknung mindestens so genau planen wie die Veg-Phase"]},{"type":"definition","heading":"Schritt 3: Duengung defensiv und phasenbezogen steuern","content":["Studien zu NPK-Fertigation bei Cannabis zeigen, dass Ueberversorgung - besonders mit Stickstoff in spaeteren Phasen - Ertrag und Qualitaet eher verschlechtern kann. Beginne deshalb unterhalb der Hersteller-Maximalangaben und steigere nur bei klarer Pflanzenreaktion.","Achte darauf, dass Lichtintensitaet, Klima und Wurzelzone zur Naehrstoffstaerke passen. Ohne diese Basis bringt mehr EC kaum Nutzen und erhoeht das Risiko fuer Blockaden oder Stressmarker."],"checklist":["pH und EC der Loesung in fixer Reihenfolge messen","Keine Booster einsetzen, solange Basisprozesse noch schwanken","Ab Blueteeinleitung Stickstoff nicht weiter aggressiv steigern"]},{"type":"definition","heading":"Schritt 4: Ernte nicht raten, sondern beobachten","content":["Einsteiger profitieren von klaren Reifeindikatoren statt Kalenderdenken. Beobachte Trichome, Pflanzenvitalitaet, Klima und Trocknungsplanung als zusammenhaengenden Prozess.","Direkt nach der Ernte entscheidet sauberes Trocknen ueber Aroma, Schimmelrisiko und Konsistenz. Professionelle Teams behandeln Postharvest als Teil des Grows und nicht als letzten Nebenjob."],"checklist":["Vor der Ernte Trocknungsraum auf Temperatur und RH vorbereiten","Trichomkontrolle mit Lupe oder Mikroskop durchfuehren","Nach dem Run drei Dinge notieren: Fehler, Korrektur, Ergebnis"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'anbau'), 'foundational'::knowledge_difficulty, 'published'::knowledge_status, 14, 5, 'Ein klarer Einstieg in Setup, Klima, Bewaesserung und Erntefenster - aufgebaut auf belastbaren Grundlagen aus Forschung und bewaehrten Profi-Routinen.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('how-to-grow-cannabis-fortgeschritten-tutorial', 'How to Grow Cannabis: Schritt-fuer-Schritt fuer Fortgeschrittene', 'Wie du ein stabiles Setup in ein datengestuetztes Produktionssystem verwandelst - mit sauberer Klima-, Feed- und Canopy-Steuerung.', '[{"type":"definition","heading":"Schritt 1: Zielkorridore pro Phase definieren","content":["Fortgeschrittene Grows scheitern selten an fehlendem Equipment, sondern an unklaren Sollwerten. Lege pro Phase Zielbereiche fuer Blattabstand zum Licht, Klima, Bewaesserungsfrequenz und Feed-Staerke fest.","Die Forschung zu Cannabis-Lichtphysiologie und NPK-Reaktion zeigt deutlich, dass Input nur dann sinnvoll steigt, wenn Photosynthese, Wurzelraum und Klima dazu passen."],"checklist":["Wochenplan fuer Veg, Stretch und Hauptbluete schreiben","Blatttemperatur oder plausiblen Offset in die VPD-Berechnung integrieren","Entscheidungsregeln fuer Hoeher- oder Runterfahren von EC festlegen"]},{"type":"definition","heading":"Schritt 2: Canopy aktiv fuehren statt nur reagieren","content":["Gleichmaessige Lichtverteilung ist ein Prozess, kein Zufall. Arbeite mit Entlaubung, Training und Hoehenmanagement so, dass Licht, Luftstrom und Reife moeglichst homogen bleiben.","Professionelle Grower behandeln die Canopy als produktive Flaeche. Jede dunkle, feuchte oder chaotische Zone wird spaeter zum Risiko fuer Minderertrag, Schimmel oder ungleichmaessige Reife."],"checklist":["Canopy-Fotos jede Woche aus gleichem Winkel machen","Ungueltige Schattenzonen konsequent reduzieren","Lichtabstand und Hotspots nach jedem Training neu kontrollieren"]},{"type":"definition","heading":"Schritt 2b: Wochenplan fuer Performance ohne Kontrollverlust","content":["Woche 1-2 Veg: Basiswerte bestaetigen. Sensorik, Giessfrequenz und Start-Feed nur so hoch fahren, dass Pflanzen sichtbar sauber reagieren. Abweichungen sofort notieren statt spaeter deuten.","Woche 3-4 Veg: Kronendach angleichen, erste Trainingsentscheidungen sauber dokumentieren und Wurzelraum-Daten mit dem Blattbild zusammen lesen. Ziel ist Homogenitaet, nicht spektakulaeres Einzelwachstum.","Woche 5 Stretch: Licht und Klima jetzt taeglich mit dem Wuchs koppeln. Stretch ist die Phase, in der schlechte Zielkorridore spaeter am teuersten werden.","Woche 6-8 Hauptbluete: Drain-Trends, K/Ca-Balance und Luftbewegung eng pruefen. Je dichter die Blueten werden, desto weniger Fehlertoleranz hat das System.","Woche 9+ Finish und Review: Reifehomogenitaet, Problemzonen und Ertragsverteilung dokumentieren. Das ist die Datenbasis fuer den naechsten Optimierungsschritt."],"checklist":["Stretch-Woche nicht ohne taegliche Licht- und Klima-Kontrolle laufen lassen","Hauptbluete als Risiko- und nicht nur als Ertragsphase behandeln","Am Zyklusende immer Review vor der naechsten Aenderung machen"]},{"type":"nutrient_interactions","heading":"Schritt 3: Nährstoffgabe und Wurzelraum datenbasiert steuern","content":["Jetzt reicht Bauchgefuehl nicht mehr. Vergleiche Soll-EC, Ist-Drain, Pflanzenreaktion und Trocknungsdauer gemeinsam. Gerade in Coco oder anderen schnell reagierenden Medien sind kleine Trends wichtiger als Einmalmessungen.","Peer-reviewte Cannabis-Studien zu Substraten und Fertigation belegen, dass Kalium-, Stickstoff- und pH-Management phasenabhaengig optimiert werden muessen. Zu spaete Reaktionen kosten Bluetenmasse und Qualitaet."],"checklist":["Drain-EC und pH an festen Wochentagen messen","Ca/Mg nur mit Kontext von Medium und Wasserwerten anpassen","Auffaellige Blattbilder immer mit Wurzelzonen- und Klima-Daten abgleichen"]},{"type":"definition","heading":"Schritt 4: Ertrag und Qualitaet mit Run-Review sichern","content":["Fortgeschrittene Grower dokumentieren nicht nur, dass ein Run gut lief, sondern warum. Vergleiche Ertrag, Trimmanteil, Reifehomogenitaet, Duftprofil und Problemzonen je Durchlauf.","Die beste Optimierung entsteht aus wenigen, klaren Hypothesen fuer den naechsten Run. Ein Review-System verhindert, dass dieselben Fehler trotz gutem Equipment wiederholt werden."],"checklist":["Run-Review in Klima, Bewaesserung, Feed, Canopy und Postharvest gliedern","Nur zwei bis drei Verbesserungen fuer den Folgezyklus definieren","Qualitaetsverlust nicht nur auf Genetik schieben, sondern Prozessdaten pruefen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'anbau'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 16, 5, 'Wie du ein stabiles Setup in ein datengestuetztes Produktionssystem verwandelst - mit sauberer Klima-, Feed- und Canopy-Steuerung.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('how-to-grow-cannabis-profi-tutorial', 'How to Grow Cannabis: Schritt-fuer-Schritt fuer Profis', 'Ein fortlaufendes Betriebsmodell fuer Teams mit hoher Datendichte, SOPs, Chargendenken und reproduzierbarer Premium-Qualitaet.', '[{"type":"definition","heading":"Schritt 1: Betrieb ueber SOPs und Freigabekriterien fuehren","content":["Professionelle Grows werden ueber Standards, nicht ueber Tagesstimmung gesteuert. Definiere SOPs fuer Raumvorbereitung, Stecklingsannahme, Bewaesserung, Sensor-Checks, Hygiene und Postharvest-Uebergaben.","Freigabekriterien je Phase helfen, dass Teams nur dann skalieren oder umstellen, wenn die Basis stabil ist. Ohne diese Gates wird jedes Problem zu teuer und schwer reproduzierbar."],"checklist":["SOP-Versionen mit Datum und Verantwortlichkeit pflegen","Phasen-Gates fuer Veg, Stretch, Bluete und Ernte schriftlich definieren","Abweichungen immer mit CAPA-Logik dokumentieren"]},{"type":"environmental_factors","heading":"Schritt 2: Klima, Licht und Feed als verknuepfte Datenspuren lesen","content":["Auf Profi-Niveau werden keine Einzelwerte diskutiert, sondern Trends: Sensor-Drift, Zonenunterschiede, Bewaesserungsfenster, PPFD-Verteilung, Blattmasse und Drain-Verhalten. Erst daraus entstehen belastbare Entscheidungen.","Studien zu Cannabis-Produktionssystemen und Erfahrungen aus professionellen Indoor-Setups zeigen, dass die groessten Gewinne aus konsistenter Standardisierung und frueher Abweichungserkennung kommen."],"checklist":["Zone gegen Zone vergleichen statt nur Mittelwerte lesen","Messgeraete nach Kalibrierintervall sperren oder freigeben","Klima- und Feed-Daten mit Ereignislog verknuepfen"]},{"type":"definition","heading":"Schritt 2b: Produktionswochen als wiederholbares Betriebsschema","content":["Woche 0 Pre-Flight: Raumfreigabe, Sensorstatus, Hygiene, Wasser und Material muessen vor Pflanzenannahme validiert sein. Ohne saubere Startfreigabe beginnt jede Charge mit Blindflug.","Woche 1-3 Etablierung: Clone-Qualitaet, Anwuchsquote und Zonenunterschiede eng monitoren. Jetzt werden SOP-Luecken sichtbar, bevor sie spaeter als Ertragsproblem auftreten.","Woche 4-6 Produktionsdruck: Stretch, Canopy-Dichte und Klima-Kopplung erzeugen die hoechste operative Last. Schichtuebergaben und Event-Logging muessen hier besonders sauber sein.","Woche 7-9 Reife und Risikoabwehr: Botrytis-, Hygiene- und Trockenmasse-Risiken steigen. Freigabekriterien fuer Erntefenster sollten nicht nur auf Optik, sondern auf Charge, Zone und Laborlogik beruhen.","Woche 10+ Postharvest und CAPA: Trocknung, Curing, Labor, Sperrentscheidungen und Review muessen in einer geschlossenen Prozessschleife enden. Erst dann ist die Charge wirklich abgeschlossen."],"checklist":["Jede Charge mit Pre-Flight und Exit-Review starten und beenden","Schichtwechsel nur mit dokumentiertem Ereignisstand uebergeben","CAPA-Massnahmen spaetestens im Folgezyklus verifizieren"]},{"type":"definition","heading":"Schritt 3: Risiko aktiv managen - Hygiene, Pathogene, Lieferkette","content":["Premium-Qualitaet scheitert oft nicht an Wuchs, sondern an Hygiene, Probenahme und Nachverfolgbarkeit. Integriere Clone-Hygiene, Schimmelpraevention, Wasserqualitaet und Lieferantenkontrolle in denselben Managementrahmen wie Licht und Ertrag.","Gerade bei hoher Pflanzendichte oder engen Takten werden kleine Hygienefehler schnell zum Chargenproblem. Profi-Grower planen deshalb Risikoabwehr als Kernprozess ein."],"checklist":["Hygiene-SOP mit Verantwortlichkeiten pro Schicht festlegen","Wasser, Werkzeuge und Clone-Zugaenge als Risikopunkte auditieren","Fruehwarnsignale fuer Pathogene und Schaedlinge in Reviews aufnehmen"]},{"type":"definition","heading":"Schritt 4: Nach der Ernte beginnt die naechste Prozessschleife","content":["Postharvest, Curing und Laborlogik gehoeren in denselben Performance-Zyklus wie die Kulturphase. Nur so lassen sich Qualitaetsverluste, Chargenunterschiede und Vermarktungsprobleme systematisch beheben.","Ein Profi-Tutorial endet deshalb nicht mit dem Chop. Es endet mit Freigabe, Review, Datenarchiv und klarer Hypothese fuer den naechsten Durchlauf."],"checklist":["Trocknung und Curing mit eigenen SOPs und Alarmgrenzen fahren","Laborergebnisse gegen Prozessdaten spiegeln","Nach jeder Charge ein Review mit QA, Cultivation und Postharvest machen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'anbau'), 'advanced'::knowledge_difficulty, 'published'::knowledge_status, 18, 5, 'Ein fortlaufendes Betriebsmodell fuer Teams mit hoher Datendichte, SOPs, Chargendenken und reproduzierbarer Premium-Qualitaet.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('naehrstoffblockaden-und-antagonismen', 'Naehrstoffblockaden und Antagonismen', 'Warum trotz ausreichender Duengewerte Mangelbilder auftreten koennen und wie Blockaden sauber eingeordnet werden.', '[{"type":"definition","heading":"Kontext und Einordnung","content":["Dieser Beitrag ordnet das Thema fuer Teams und Nutzer in einen belastbaren Rahmen ein, damit Entscheidungen nicht nur auf Einzelbeobachtungen beruhen.","Im Fokus stehen nachvollziehbare Kriterien, saubere Begriffsnutzung und der Bezug zu realen Prozessdaten."]},{"type":"definition","heading":"Praxisorientierte Umsetzung","content":["Der Inhalt verbindet Grundlagen mit operativen Checks, damit das Thema nicht nur verstanden, sondern im Alltag konsistent angewendet werden kann.","Besonders fuer einen grossen ersten Drop entsteht so ein klarer Mehrwert in Orientierung und Vergleichbarkeit."],"checklist":["Kriterien vorab festlegen","Dokumentation mit Zeitstempel pflegen","Abweichungen und Korrekturen nachvollziehbar erfassen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'anbau'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 8, 5, 'Warum trotz ausreichender Duengewerte Mangelbilder auftreten koennen und wie Blockaden sauber eingeordnet werden.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('genetik-und-phaenotyp-selektion', 'Genetik und Phaenotyp-Selektion', 'Wie du genetische Linien vergleichst, stabile Kandidaten auswaehlst und Drift ueber Generationen vermeidest.', '[{"type":"definition","heading":"Vorbereitung eines belastbaren Hunts","content":["Lege harte Kriterien fest: Morphologie, Stressresistenz, Aroma, Ertrag und Nachernteverhalten.","Nimm vorab Ausschlussregeln auf, damit Entscheidungen nicht nach Sympathie fallen."]},{"type":"definition","heading":"Auswahl und Verifizierung","content":["Top-Kandidaten sollten in mindestens einem Bestaetigungsdurchlauf erneut performen.","Nur reproduzierbare Linien sind fuer den operativen Betrieb sinnvoll."],"checklist":["Blindvergleich der Kandidaten","Labordaten mit Sensorik korrelieren","Mutterlinien rotieren und Backup-Clone halten"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'genetik'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 8, 4, 'Wie du genetische Linien vergleichst, stabile Kandidaten auswaehlst und Drift ueber Generationen vermeidest.', 'de', '2026-03-26'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('terpene-und-wirkprofil', 'Terpene und Wirkprofil', 'Welche Rolle Terpene fuer Aroma und Produktprofil spielen und wie man Marketingaussagen sauber von Daten trennt.', '[{"type":"definition","heading":"Was Terpene wirklich leisten","content":["Terpene formen das Aroma deiner Ernte und beeinflussen, wie das Produkt wahrgenommen wird.","Sie ersetzen keine Laborwerte fuer Cannabinoide — aber sie erklaeren, warum zwei Chargen mit gleichen THC-Werten unterschiedlich wirken."]},{"type":"definition","heading":"Warum das deine Qualitaet direkt betrifft","content":["Terpene sind fluechtig: Hitze, Luft und Licht bauen sie ab — schlechte Lagerung zerstoert das Profil.","Wer Terpenverluste versteht, kann Ernte, Curing und Lagerung konkret verbessern."]},{"type":"definition","heading":"In SecretLeaf relevant wenn","content":["du Chargen vergleichen willst und nicht weisst, warum sich Aroma unterscheidet","dein Curing oder deine Lagerung das Profil veraendern und du den Grund nicht kennst","du Laborwerte einordnen moechtest und nicht weisst, welche Terpenangabe belastbar ist"]},{"type":"definition","heading":"Was du konkret tun solltest","content":[],"checklist":["Ernte bei < 22°C trocknen und lagern — jeder Grad mehr beschleunigt Terpenverlust messbar","Glasbehaelter luftdicht verschliessen — Sauerstoffkontakt ist der groesste Einzelfaktor fuer Profilveraenderung","COA-Terpenangabe nur vergleichen, wenn gleiche Methode und Probenahmezeit dokumentiert sind"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'terpene'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 10, 4, 'Welche Rolle Terpene fuer Aroma und Produktprofil spielen und wie man Marketingaussagen sauber von Daten trennt.', 'de', '2026-03-26'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('inhalation-vs-edibles', 'Inhalation vs. Edibles: Wirkung und Timing', 'Vergleich von Aufnahmewegen, Onset-Zeit, Wirkdauer und Risiken fuer bessere Aufklaerung.', '[{"type":"definition","heading":"Pharmakokinetik in der Praxis","content":["Inhalation wirkt typischerweise schnell, klingt aber frueher ab.","Orale Aufnahme startet spaeter und kann deutlich laenger anhalten."]},{"type":"definition","heading":"Sicherheitsprinzipien","content":["Setze klare Wartefenster vor Nachdosierung und kombiniere nicht mit Alkohol.","Plane Konsum nur in stabilen Umgebungen ohne unmittelbare Pflichten."],"checklist":["Niedrig starten","Wartezeit vor Redose einhalten","Keine Teilnahme am Strassenverkehr"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'konsumformen'), 'foundational'::knowledge_difficulty, 'published'::knowledge_status, 7, 4, 'Vergleich von Aufnahmewegen, Onset-Zeit, Wirkdauer und Risiken fuer bessere Aufklaerung.', 'de', '2026-03-26'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('coa-richtig-lesen', 'COA richtig lesen', 'So interpretierst du Laborberichte zu Potenz, Terpenen und Kontaminanten ohne in Marketingfallen zu tappen.', '[{"type":"definition","heading":"Was du zuerst pruefst","content":["Schau zuerst: Ist die Chargennummer identisch mit deiner Ware? Ist das Analysedatum aktuell?","Ohne diesen Match ist das COA wertlos — es koennte jedes andere Produkt beschreiben."],"checklist":["Chargennummer identisch zur Ware","Aktuelles Analysedatum","Methoden und Einheiten klar ausgewiesen"]},{"type":"definition","heading":"Warum ein COA deine Kaufentscheidung veraendert","content":["Ein COA zeigt dir, was du wirklich bekommst — Potenz, Terpene, Schadstoffe.","Ohne Laborbericht ist jede Qualitaetsaussage Marketing, keine Tatsache."]},{"type":"definition","heading":"Kontaminanten richtig einordnen","content":["Einzelne Spuren unter Grenzwert sind anders zu bewerten als systematische Auffaelligkeiten.","Entscheidend ist: Sind Messgrenzen (LOQ/LOD) angegeben? Fehlen sie, ist der Befund nicht vergleichbar."]},{"type":"definition","heading":"In SecretLeaf relevant wenn","content":["du ein Produkt kaufst und pruefen willst, ob die Angaben stimmen","du Chargen vergleichst und verstehen willst, warum Qualitaet schwankt","du entscheiden moechtest, ob einem Lieferanten zu vertrauen ist"]},{"type":"definition","heading":"Was du konkret tun solltest","content":[],"checklist":["Chargennummer auf COA mit der auf der Verpackung abgleichen — immer, kein Ausnahme","Pruefe: Sind Kontaminantenliste und Messmethode vollstaendig? Sonst anfragen oder Lieferant wechseln","Speichere COAs chargenbezogen in deinem Grow-Log — nur so kannst du spaeter vergleichen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'qualitaet'), 'foundational'::knowledge_difficulty, 'published'::knowledge_status, 7, 4, 'So interpretierst du Laborberichte zu Potenz, Terpenen und Kontaminanten ohne in Marketingfallen zu tappen.', 'de', '2026-03-26'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('pgr-und-kontaminanten', 'PGR und Kontaminanten erkennen', 'Worauf Verbraucher achten sollten und welche Laborwerte fuer sichere Entscheidungen relevant sind.', '[{"type":"definition","heading":"Von der Beobachtung zur Bewertung","content":["Verlasse dich nicht nur auf Geruch oder Dichte der Blueten.","Sicherheitsurteile sollten auf Laborwerten, Historie und Prozessdaten beruhen."]},{"type":"definition","heading":"Risikomanagement im Alltag","content":["Baue Sperrlogik fuer auffaellige Chargen in den operativen Ablauf ein.","Kommuniziere transparent, warum Produkte zurueckgehalten oder nachgetestet werden."]}]'::jsonb, (select id from public.knowledge_categories where slug = 'sicherheit'), 'foundational'::knowledge_difficulty, 'published'::knowledge_status, 6, 4, 'Worauf Verbraucher achten sollten und welche Laborwerte fuer sichere Entscheidungen relevant sind.', 'de', '2026-03-26'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('integrierte-schaedlingspraevention-grow', 'Integrierte Schaedlingspraevention im Grow', 'Wie Monitoring, Hygiene und Frueherkennung Ausfaelle verhindern, ohne blind in Chemie oder Panik zu verfallen.', '[{"type":"definition","heading":"Von der Reaktion zur Praevention","content":["Viele Grow-Probleme eskalieren, weil Monitoring erst dann beginnt, wenn sichtbare Schaeden da sind.","Ein sauberes IPM verknuepft Eingangskontrolle, Raumhygiene, Teamdisziplin und dokumentierte Eskalationsstufen."]},{"type":"definition","heading":"Was in einen belastbaren IPM-Plan gehoert","content":["Lege fest, welche Zonen kontrolliert werden, wie Funde dokumentiert werden und wer ueber Massnahmen entscheidet.","Nur so bleiben Eingriffe verhaeltnismaessig und auditierbar."],"checklist":["Quarantaene fuer neue Pflanzen oder Material","Woechentliche Monitoring-Route mit Foto-Dokumentation","Reinigungsplan fuer Werkzeuge, Schuhe und Flaechen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'anbau'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 8, 4, 'Wie Monitoring, Hygiene und Frueherkennung Ausfaelle verhindern, ohne blind in Chemie oder Panik zu verfallen.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('mutterpflanzen-und-clone-hygiene', 'Mutterpflanzen und Clone-Hygiene', 'Wie du gesunde Mutterlinien fuehrst, Kreuzkontamination vermeidest und Clone-Programme reproduzierbar machst.', '[{"type":"definition","heading":"Warum Mutterlinien oft unterschuetzt werden","content":["Viele Systeme fokussieren nur auf den Run, nicht auf die Quelle des Pflanzenmaterials. Genau dort entstehen aber oft die spaeteren Probleme.","Eine muede, kontaminierte oder falsch gefuehrte Mutterlinie zieht Fehler durch den gesamten Prozess."]},{"type":"definition","heading":"So sieht ein sauberes Clone-Programm aus","content":["Definiere Schnittstandards, Hygieneprotokolle, Bewurzelungsfenster und Ausschlusskriterien fuer schwache Stecklinge.","Halte mehrere Backups und trenne wertvolle Linien gegen Verlust oder Verwechslung."],"checklist":["Werkzeug vor jedem Schnitt desinfizieren","Mutterpflanzen regelmaessig verjuengen","Clone-Raten und Ausfaelle pro Linie dokumentieren"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'genetik'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 8, 4, 'Wie du gesunde Mutterlinien fuehrst, Kreuzkontamination vermeidest und Clone-Programme reproduzierbar machst.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('thc-zu-cbn-abbau-und-oxidation', 'THC zu CBN: Abbau und Oxidation', 'Warum Wirkstoffprofile bei Licht, Hitze und Zeit kippen und wie diese Veraenderungen sauber eingeordnet werden.', '[{"type":"definition","heading":"Wie Abbauprozesse entstehen","content":["Chemische Profile veraendern sich nach der Ernte weiter. Ein gemessener Wert vom Freigabetag ist daher nicht zwingend identisch mit dem Zustand Monate spaeter.","Besonders kritisch sind Kombinationen aus Sauerstoffkontakt, Waerme und langen Lagerzeiten."]},{"type":"definition","heading":"Was das fuer Qualitaet und Kommunikation bedeutet","content":["Produktprofile muessen mit Produktions- und Lagerdaten zusammen bewertet werden. Andernfalls werden normale Alterungsprozesse schnell fehlgedeutet.","Fuer Plattformen und Labore sind klare Hinweise auf Probendatum, Lagerregime und Messmethode zentral."],"checklist":["Probendatum und Verpackungsstatus dokumentieren","Licht- und Sauerstoffschutz definieren","Alte und neue Chargen nicht ohne Kontext vergleichen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'chemie'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 7, 4, 'Warum Wirkstoffprofile bei Licht, Hitze und Zeit kippen und wie diese Veraenderungen sauber eingeordnet werden.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('lagerung-und-terpenverlust-vermeiden', 'Lagerung und Terpenverlust vermeiden', 'Warum Verpackung, Temperatur und Sauerstoffkontakt das Aromaprofil staerker formen, als viele Content-Seiten zugeben.', '[{"type":"definition","heading":"Warum Aroma so schnell kippt","content":["Terpene verdampfen oder veraendern sich leichter als viele andere Stoffklassen. Schon die Kombination aus Lagerzeit und unguenstiger Verpackung kann viel kosten.","Deshalb ist das urspruengliche Profil nicht automatisch identisch mit dem, was spaeter beim Nutzer ankommt."]},{"type":"definition","heading":"Welche Verpackungslogik funktioniert","content":["Ziel ist nicht nur dicht, sondern kontrolliert: wenig Sauerstoff, moeglichst wenig Licht und stabile Temperaturen.","Fuer Teams lohnt es sich, Packmittel und Reklamationsdaten gemeinsam zu betrachten."],"checklist":["Lager- und Transporttemperaturen begrenzen","Lichtschutz als Pflichtkriterium behandeln","Aromareklamationen mit Chargenalter verknuepfen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'terpene'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 7, 4, 'Warum Verpackung, Temperatur und Sauerstoffkontakt das Aromaprofil staerker formen, als viele Content-Seiten zugeben.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('bubble-hash-qualitaetskriterien', 'Bubble Hash: Qualitaetskriterien', 'Welche Faktoren fuer Reinheit, Stabilitaet und Vergleichbarkeit wirklich zaehlen und welche Kurzlabels wenig aussagen.', '[{"type":"definition","heading":"Was Bubble Hash professionell auszeichnet","content":["Fachlich relevant sind Reinheit, sensorische Klarheit, Lagerstabilitaet und Kontaminantenstatus. Szeneetiketten allein reichen nicht.","Gerade bei hochwertigen Produkten entscheiden Nachbehandlung und Dokumentation ueber echte Vergleichbarkeit."]},{"type":"definition","heading":"Wo die typischen Fehlbewertungen liegen","content":["Begriffe aus Communities oder Shops klingen praezise, sind aber oft nicht standardisiert. Ohne Mess- und Chargenkontext bleiben sie begrenzt aussagekraeftig.","Plattformen sollten daher eigene Bewertungskriterien definieren."],"checklist":["Chargen-ID und Lagerbedingungen erfassen","Kontaminanten- und Stabilitaetsdaten einbeziehen","Szenegrad nie ohne Kriterienliste verwenden"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'konzentrate'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 8, 4, 'Welche Faktoren fuer Reinheit, Stabilitaet und Vergleichbarkeit wirklich zaehlen und welche Kurzlabels wenig aussagen.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('rosin-einordnung-ohne-hype', 'Rosin einordnen ohne Hype', 'Wie Input-Material, Temperaturbelastung und Nachbehandlung das Ergebnis formen und warum das besser ist als reine Trendbegriffe.', '[{"type":"definition","heading":"Warum Rosin so oft ueberhoeht wird","content":["Der Begriff steht in vielen Communities fuer Hochwertigkeit. Das ist verstaendlich, aber fachlich zu kurz.","Ohne Blick auf Ausgangsmaterial, Prozesssauberkeit und Stabilitaet bleibt die Einordnung oberflaechlich."]},{"type":"definition","heading":"Wie du Rosin professionell beschreibst","content":["Sprich ueber Vorstufe, Chargenkontext, Lagerung und Analytik. Das schafft mehr Vertrauen als Szenevokabular allein.","Gerade auf grossen Seiten lohnt sich ein standardisiertes Datenraster."],"checklist":["Input-Material offen benennen","Stabilitaet und Kontaminanten mitdenken","Trendbegriffe nur mit Kriterien erklaeren"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'konzentrate'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 8, 4, 'Wie Input-Material, Temperaturbelastung und Nachbehandlung das Ergebnis formen und warum das besser ist als reine Trendbegriffe.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('pestizidklassen-und-rueckstandsrisiken', 'Pestizidklassen und Rueckstandsrisiken', 'Eine Einordnung der wichtigsten Stoffgruppen, warum Listen allein nicht genuegen und wie Rueckstandsberichte gelesen werden sollten.', '[{"type":"definition","heading":"Warum Rueckstandslisten oft zu simpel gelesen werden","content":["Eine Liste mit vielen Namen wirkt eindrucksvoll, sagt aber wenig, wenn Nachweisgrenzen, Methoden und relevante Stoffe unklar bleiben.","Fuer serioese Bewertung braucht es mehr als ein gruenes Haekchen."]},{"type":"definition","heading":"Wie ein sauberer Rueckstandscheck aussieht","content":["Pruefe Stoffabdeckung, Grenzwerte, Methode, Chargenbezug und Testfrequenz. Erst dann wird aus Daten ein Sicherheitsurteil.","Das gilt fuer Plattformen genauso wie fuer Einkaufsteams."],"checklist":["Panelabdeckung dokumentieren","Grenzwerte regional zuordnen","Rueckstandsstrategie pro Lieferant festhalten"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'sicherheit'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 8, 4, 'Eine Einordnung der wichtigsten Stoffgruppen, warum Listen allein nicht genuegen und wie Rueckstandsberichte gelesen werden sollten.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('lagerung-verpackung-und-lichtschutz', 'Lagerung, Verpackung und Lichtschutz', 'Wie Verpackungssysteme die reale Produktqualitaet mitbestimmen und warum Lagerung ein Kernteil der Qualitaetssicherung ist.', '[{"type":"definition","heading":"Warum Verpackung mehr ist als Huelle","content":["Packmittel bestimmen mit, wie stabil Aroma, Wirkstoffprofil und mikrobiologische Sicherheit ueber Zeit bleiben.","Gerade bei hochwertigen Produkten ist das ein direkter Qualitaetshebel."]},{"type":"definition","heading":"Welche Fragen gute Lagerung beantwortet","content":["Wie alt ist die Charge, wie wurde sie transportiert und war sie Licht oder Hitze ausgesetzt? Diese Punkte sollten nie unsichtbar bleiben.","Erst zusammen mit Reklamationen und Analytik entsteht ein lernfaehiges System."],"checklist":["Packmittel nach Produktklasse auswaehlen","Lager- und Transportbedingungen dokumentieren","Profilverlust mit Packmitteltests vergleichen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'qualitaet'), 'foundational'::knowledge_difficulty, 'published'::knowledge_status, 7, 4, 'Wie Verpackungssysteme die reale Produktqualitaet mitbestimmen und warum Lagerung ein Kernteil der Qualitaetssicherung ist.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('stressmarker-frueh-erkennen', 'Stressmarker frueh erkennen', 'Fruehe Hinweise auf Klima-, Licht- und Wurzelstress erkennen, bevor Ertrag und Qualitaet kippen.', '[{"type":"definition","heading":"Kontext und Einordnung","content":["Dieser Beitrag ordnet das Thema fuer Teams und Nutzer in einen belastbaren Rahmen ein, damit Entscheidungen nicht nur auf Einzelbeobachtungen beruhen.","Im Fokus stehen nachvollziehbare Kriterien, saubere Begriffsnutzung und der Bezug zu realen Prozessdaten."]},{"type":"definition","heading":"Praxisorientierte Umsetzung","content":["Der Inhalt verbindet Grundlagen mit operativen Checks, damit das Thema nicht nur verstanden, sondern im Alltag konsistent angewendet werden kann.","Besonders fuer einen grossen ersten Drop entsteht so ein klarer Mehrwert in Orientierung und Vergleichbarkeit."],"checklist":["Kriterien vorab festlegen","Dokumentation mit Zeitstempel pflegen","Abweichungen und Korrekturen nachvollziehbar erfassen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'anbau'), 'foundational'::knowledge_difficulty, 'published'::knowledge_status, 6, 4, 'Fruehe Hinweise auf Klima-, Licht- und Wurzelstress erkennen, bevor Ertrag und Qualitaet kippen.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('naehrstoffbedarf-cannabis-lebenszyklus', 'Naehrstoffbedarf im Cannabis-Lebenszyklus', 'Phasenweise Uebersicht des NPK-, Ca- und Mg-Bedarfs bei Photoperiodisch- und Autoflower-Pflanzen in Erde und Coco – basierend auf peer-reviewten Studien.', '[{"type":"definition","heading":"Kontext und Einordnung","content":["Dieser Beitrag ordnet das Thema fuer Teams und Nutzer in einen belastbaren Rahmen ein, damit Entscheidungen nicht nur auf Einzelbeobachtungen beruhen.","Im Fokus stehen nachvollziehbare Kriterien, saubere Begriffsnutzung und der Bezug zu realen Prozessdaten."]},{"type":"definition","heading":"Praxisorientierte Umsetzung","content":["Der Inhalt verbindet Grundlagen mit operativen Checks, damit das Thema nicht nur verstanden, sondern im Alltag konsistent angewendet werden kann.","Besonders fuer einen grossen ersten Drop entsteht so ein klarer Mehrwert in Orientierung und Vergleichbarkeit."],"checklist":["Kriterien vorab festlegen","Dokumentation mit Zeitstempel pflegen","Abweichungen und Korrekturen nachvollziehbar erfassen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'anbau'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 10, 4, 'Phasenweise Uebersicht des NPK-, Ca- und Mg-Bedarfs bei Photoperiodisch- und Autoflower-Pflanzen in Erde und Coco – basierend auf peer-reviewten Studien.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('substrat-vergleich-coco-erde-hydro', 'Substratvergleich: Coco, Erde und Hydro', 'Was peer-reviewte Studien ueber Ertrag, EC-Toleranz und Pflegeaufwand bei den drei Hauptsubstraten sagen – inklusive praktischer Empfehlungen fuer Hobby-Grower.', '[{"type":"definition","heading":"Kontext und Einordnung","content":["Dieser Beitrag ordnet das Thema fuer Teams und Nutzer in einen belastbaren Rahmen ein, damit Entscheidungen nicht nur auf Einzelbeobachtungen beruhen.","Im Fokus stehen nachvollziehbare Kriterien, saubere Begriffsnutzung und der Bezug zu realen Prozessdaten."]},{"type":"definition","heading":"Praxisorientierte Umsetzung","content":["Der Inhalt verbindet Grundlagen mit operativen Checks, damit das Thema nicht nur verstanden, sondern im Alltag konsistent angewendet werden kann.","Besonders fuer einen grossen ersten Drop entsteht so ein klarer Mehrwert in Orientierung und Vergleichbarkeit."],"checklist":["Kriterien vorab festlegen","Dokumentation mit Zeitstempel pflegen","Abweichungen und Korrekturen nachvollziehbar erfassen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'anbau'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 9, 4, 'Was peer-reviewte Studien ueber Ertrag, EC-Toleranz und Pflegeaufwand bei den drei Hauptsubstraten sagen – inklusive praktischer Empfehlungen fuer Hobby-Grower.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('hash-typen-vergleichen', 'Hash-Typen professionell eingeordnet', 'Ursprung, Verfahrensfamilien, klassische und moderne Typen sowie klare Systematik: was wirklich zusammengehoert und wie man Qualitaet fachlich bewertet.', '[{"type":"definition","heading":"1) Taxonomie: Welche Hash-Arten gibt es wirklich?","content":["Professionell wird Hash zuerst nach Trennprinzip geordnet und erst danach nach Handelsnamen. Das verhindert Verwechslungen zwischen Stilbegriffen und Technik.","Verfahrensfamilien: (A) mechanisch trocken getrennt (Dry Sift/Kief), (B) eiswasserbasiert getrennt (Ice Water/Bubble), (C) hand- oder pressbasiert verdichtet (z. B. Charas, klassischer Presshash), (D) loesungsmittelbasierte Extrakte mit optionaler Weiterverarbeitung zu hash-aehnlichen Endformen.","Was gehoert zusammen: Dry Sift und traditionelle Kief-Linien sind eine Familie; Bubble und daraus gepresste Rosin-Linien sind eine zweite Familie; historische Presshash-Stile bilden eine kultur- und prozesshistorische Gruppe."]},{"type":"definition","heading":"2) Historischer Ursprung und regionale Stilbegriffe","content":["Historisch entstanden verschiedene Hash-Kulturen in unterschiedlichen Regionen mit eigenen Rohwaren, Klimabedingungen und Presstechniken.","Nordafrika ist eng mit Kief-/Siebtraditionen verbunden; in Teilen Zentral- und Suedasiens sind handgeriebene und gepresste Formen historisch praegend; in der Levante entwickelten sich eigene Presshash-Stile mit spezifischer Reifung und Marktlogik.","Wichtig: Regionenamen sind Stilmarker, aber keine automatische Garantie fuer Reinheit, Potenz oder Sicherheitsprofil."]},{"type":"definition","heading":"3) Verfahrensfamilien im professionellen Vergleich","content":["Dry Sift/Kief: trocken-mechanische Trennung. Staerken liegen in klarer Prozesslogik und guter Skalierbarkeit, Risiken liegen in Verunreinigung durch Pflanzenreste bei ungenauer Fraktionierung.","Ice Water/Bubble: nasskalte Trennung. Staerken sind hohe Reinheitsfenster bei sauberer Prozessfuehrung; kritische Punkte sind Trocknungsmanagement, Wasseraktivitaet und mikrobiologische Stabilitaet.","Presshash/Traditionsstile: Verdichtung und Reifung sind zentrale Faktoren. Ergebnisqualitaet haengt stark von Ausgangsfraktion, Druck-/Waermeprofil und Lagerregime ab.","Rosin-Linien: loesungsmittelfreie Press-Weiterverarbeitung von geeigneten Vorprodukten. Qualitaet wird von Input-Material und thermischer Belastung begrenzt.","Loesungsmittelgestuetzte Extrakte: eigene Produktklasse; fuer Vergleich mit klassischem Hash muessen Restloesungsmittel- und Reinheitsdaten zwingend betrachtet werden."]},{"type":"definition","heading":"4) Welche Begriffe werden haeufig verwechselt?","content":["Kief ist nicht automatisch fertiger Presshash; Bubble ist nicht automatisch Rosin; Rosin ist ein Endprodukt aus geeigneten Vorstufen, keine Herkunftsbezeichnung.","''Full melt'', ''6 star'', ''premium'' sind Marktbegriffe und sollten stets gegen objektive Messwerte (z. B. Kontaminantenstatus, Wasseraktivitaet, Chargenvergleich) gespiegelt werden.","''Old school'' vs. ''modern'' beschreibt oft Verarbeitungskultur und Zielprofil, nicht zwingend Sicherheits- oder Qualitaetsniveau."]},{"type":"definition","heading":"5) Professionelle Bewertungsmatrix","content":["Sensorik: Klarheit der Aromen, Fremdnoten, Oxidationshinweise, konsistente Chargencharakteristik.","Physikalik: Homogenitaet, Trennverhalten bei definierter Temperatur, Stabilitaet in Lagerung und Transport.","Analytik: Cannabinoid-/Terpenprofil, Kontaminanten, mikrobiologische Parameter, ggf. Restloesungsmittel in relevanten Klassen.","Prozessqualitaet: SOP-Reifegrad, Rueckverfolgbarkeit, Reklamationsquote und Batch-to-Batch-Abweichung."],"checklist":["Jede Charge mit eindeutiger ID und Herkunftsdokumentation","COA-Pruefung inkl. Datum, Methode und Nachweisgrenzen","Lager- und Transportbedingungen pro Batch protokollieren","Abweichungen aus Sensorik und Labor im CAPA-Prozess nachhalten"]},{"type":"definition","heading":"6) Praktische Einordnung fuer Plattformen und Einkauf","content":["Baue Kataloge nicht nur nach Handelsnamen auf, sondern nach Verfahrensfamilien und Qualitaetskriterien. Das erleichtert Vergleichbarkeit und Aufklaerung.","Trenne Produktstory (Herkunft, Stil, Kultur) sauber von Compliance- und Sicherheitsdaten.","Nutze einheitliche Datenfelder fuer jede Hash-Klasse, damit Nutzer und Teams Konsistenz statt Einzelfallwissen erhalten."],"checklist":["Verfahrensfamilie als Pflichtfeld im Datenmodell","Herkunft/Stil als separates Feld, nicht als Qualitaetslabel","Einheitliche Mindestdaten fuer alle Konzentratklassen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'konzentrate'), 'advanced'::knowledge_difficulty, 'published'::knowledge_status, 16, 3, 'Ursprung, Verfahrensfamilien, klassische und moderne Typen sowie klare Systematik: was wirklich zusammengehoert und wie man Qualitaet fachlich bewertet.', 'de', '2026-03-26'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('feminisiert-vs-regular-vs-autoflower', 'Feminisiert vs. Regular vs. Autoflower', 'Welche genetischen Formate es gibt, wo ihre jeweiligen Staerken liegen und welche Missverstaendnisse haeufig sind.', '[{"type":"definition","heading":"Drei Formate, drei Einsatzgebiete","content":["Regular-Samen sind wichtig fuer Zucht und tiefe Selektion, feminisierte Linien vereinfachen viele Produktionsablaeufe und Autoflower verkuerzen bestimmte Zyklen.","Keines der Systeme ist pauschal ueberlegen. Die Entscheidung haengt von Raum, Erfahrung und Prozesszielen ab."]},{"type":"definition","heading":"Worauf du in der Praxis achten solltest","content":["Pruefe, wie stabil eine Linie tatsaechlich ist und ob die Beschreibung des Breeders mit deiner Zielumgebung zusammenpasst.","Fuer spaetere Vergleichbarkeit sind Dokumentation und Testlaeufe wichtiger als Produktversprechen."],"checklist":["Zuchtziel vor der Sortenwahl definieren","Breeder-Angaben gegen echte Grow-Daten pruefen","Leistung ueber mehrere Runs vergleichen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'genetik'), 'foundational'::knowledge_difficulty, 'published'::knowledge_status, 7, 3, 'Welche genetischen Formate es gibt, wo ihre jeweiligen Staerken liegen und welche Missverstaendnisse haeufig sind.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('cannabinoid-biosynthese-verstehen', 'Cannabinoid-Biosynthese verstehen', 'Wie Vorstufen, Enzyme und Reifeprozesse das Profil einer Pflanze formen und warum das fuer Dateninterpretation wichtig ist.', '[{"type":"definition","heading":"Was das fuer deinen Grow bedeutet","content":["Das Cannabinoid-Profil deiner Pflanze ist keine feste Groesse — es veraendert sich mit Reife, Lagerung und Prozess.","Wer das versteht, kann Erntezeitpunkt und Lagerung gezielt steuern statt auf Zufallswerte zu vertrauen."]},{"type":"advanced_considerations","heading":"Warum das Qualitaet und Profil direkt beeinflusst","content":["Zu frueh geerntet: THC-Vorstufen dominieren, Wirkprofil ist unfertig.","Zu spaet geerntet oder schlecht gelagert: THC baut ab, CBN steigt — das Profil kippt unwiderruflich."],"checklist":["Analysedaten immer mit Ernte- und Prozessdaten lesen","Minor-Werte nur mit Methodenhinweis vergleichen","COA-Datum pruefen: aeltere Proben spiegeln nicht das aktuelle Profil"]},{"type":"definition","heading":"In SecretLeaf relevant wenn","content":["du den richtigen Erntezeitpunkt bestimmen willst und Trichom-Kontrolle allein nicht reicht","Laborwerte zwischen Chargen stark schwanken und du den Grund nicht kennst","du verstehen willst, warum dein Profil sich nach Lagerung veraendert hat"]},{"type":"definition","heading":"Was du konkret tun solltest","content":[],"checklist":["Erntezeitpunkt festhalten: Datum, Trichom-Bild, Reifegrad — so kannst du Laborwerte spaeter einordnen","Lagertemperatur unter 20°C halten und Licht ausschliessen — beides beschleunigt Abbau messbar","COA-Daten immer mit Charge und Lagerbedingung verknuepfen, nicht nur ablegen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'chemie'), 'intermediate'::knowledge_difficulty, 'published'::knowledge_status, 9, 3, 'Wie Vorstufen, Enzyme und Reifeprozesse das Profil einer Pflanze formen und warum das fuer Dateninterpretation wichtig ist.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('myrcen-limonen-caryophyllen-einordnung', 'Myrcen, Limonen, Caryophyllen richtig einordnen', 'Wie bekannte Terpene fachlich beschrieben werden sollten und wo Marketing oft zu stark vereinfacht.', '[{"type":"definition","heading":"Was diese Terpene dir ueber dein Produkt sagen","content":["Myrcen, Limonen und Caryophyllen sind die drei am haeufigsten gemessenen Terpene — sie beschreiben einen Teil des Aromas, aber nicht die Wirkung.","Ein Produkt mit viel Myrcen kann trotzdem ein anderes Profil haben als ein anderes mit gleichen Werten, weil andere Bestandteile mitspielen."]},{"type":"definition","heading":"Warum das fuer Qualitaetsbewertung wichtig ist","content":["Wer nur auf das Top-Terpen schaut, bewertet ein Produkt unvollstaendig.","Qualitaet entsteht aus dem Gesamtprofil — kein einzelnes Terpen erklaert, warum eine Ernte besonders gut ist."],"checklist":["Gesamtprofil lesen, nicht nur das staerkste Terpen","Sensorischen Eindruck (Geruch, Aroma) und Laborwerte getrennt notieren","Terpenvergleiche nur bei gleicher Messmethode machen"]},{"type":"definition","heading":"In SecretLeaf relevant wenn","content":["du Chargen vergleichst und verstehen willst, warum eine Ernte aromatisch besser war","du Laborwerte liest und einordnen moechtest, ob Terpenunterschiede bedeutend sind","du dein Curing verbessern willst und wissen moechtest, welche Bedingungen das Profil sichern"]},{"type":"definition","heading":"Was du konkret tun solltest","content":[],"checklist":["Notiere beim Curing-Start das Aromaprofil sensorisch — so erkennst du spaeter Verluste","Vergleiche Terpen-COAs nur, wenn Methode und Probenahme identisch sind — sonst nicht aussagekraeftig","Bewerte Qualitaet immer mit Gesamtprofil + Sensorik + COA gemeinsam, nie mit einem Wert allein"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'terpene'), 'foundational'::knowledge_difficulty, 'published'::knowledge_status, 7, 3, 'Wie bekannte Terpene fachlich beschrieben werden sollten und wo Marketing oft zu stark vereinfacht.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('vaping-rauchen-und-verdampfen-vergleich', 'Vaping, Rauchen und Verdampfen im Vergleich', 'Wie sich Aufnahme, Belastung und Nutzererfahrung zwischen verschiedenen Inhalationsformen unterscheiden.', '[{"type":"definition","heading":"Warum die Begriffe oft durcheinandergehen","content":["Im Alltag werden Rauchen, Verdampfen und Vaping oft unscharf benutzt, obwohl Prozesse und Belastungsprofile auseinandergehen.","Genau diese Unterscheidung ist fuer serioese Aufklaerung entscheidend."]},{"type":"definition","heading":"Wie Vergleiche fair bleiben","content":["Statt absolute Sieger auszurufen, sollte Content Unterschiede in Onset, Reizstoffen, Dosierbarkeit und Fehlerquellen erklaeren.","So koennen Nutzer informierter entscheiden."],"checklist":["Konsumform klar benennen","Belastungs- und Timingunterschiede trennen","Material- und Geraetequalitaet mitberuecksichtigen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'konsumformen'), 'foundational'::knowledge_difficulty, 'published'::knowledge_status, 7, 3, 'Wie sich Aufnahme, Belastung und Nutzererfahrung zwischen verschiedenen Inhalationsformen unterscheiden.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('full-melt-und-marketingsprache', 'Full Melt und Marketingsprache', 'Warum Szene- und Shopbegriffe eine Einordnung brauchen und wie man sie auf grossen Wissensseiten sauber erklaert.', '[{"type":"definition","heading":"Warum Sprache im Konzentratbereich so aufgeladen ist","content":["Szenebegriffe transportieren Status, Erfahrung und Erwartungen. Genau deshalb muessen sie fuer neue Nutzer sauber eingeordnet werden.","Sonst wird Marketing leicht mit Messbarkeit verwechselt."]},{"type":"definition","heading":"Wie Plattformen damit umgehen sollten","content":["Erklaere Begriffe, aber knuepfe Produktbewertung an nachvollziehbare Kriterien und nicht an Szeneetiketten.","Das reduziert Fehlkaeufe und macht Kataloge professioneller."],"checklist":["Jeden Szenebegriff im Glossar definieren","Kriterien von Werbesprache trennen","Community-Begriffe nur mit Kontext darstellen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'konzentrate'), 'advanced'::knowledge_difficulty, 'published'::knowledge_status, 7, 3, 'Warum Szene- und Shopbegriffe eine Einordnung brauchen und wie man sie auf grossen Wissensseiten sauber erklaert.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
insert into public.knowledge_articles (slug, title, summary, body, category_id, difficulty, status, read_minutes, quality_score, seo_description, language, published_at, meta) values ('indoor-outdoor-anbau-vergleich', 'Indoor vs. Outdoor: Anbauvergleich Cannabis', 'Licht, Ertrag, Terpenprofil und Risikofaktoren im direkten Vergleich – was Forschung und Praxis ueber beide Anbausysteme sagen.', '[{"type":"definition","heading":"Kontext und Einordnung","content":["Dieser Beitrag ordnet das Thema fuer Teams und Nutzer in einen belastbaren Rahmen ein, damit Entscheidungen nicht nur auf Einzelbeobachtungen beruhen.","Im Fokus stehen nachvollziehbare Kriterien, saubere Begriffsnutzung und der Bezug zu realen Prozessdaten."]},{"type":"definition","heading":"Praxisorientierte Umsetzung","content":["Der Inhalt verbindet Grundlagen mit operativen Checks, damit das Thema nicht nur verstanden, sondern im Alltag konsistent angewendet werden kann.","Besonders fuer einen grossen ersten Drop entsteht so ein klarer Mehrwert in Orientierung und Vergleichbarkeit."],"checklist":["Kriterien vorab festlegen","Dokumentation mit Zeitstempel pflegen","Abweichungen und Korrekturen nachvollziehbar erfassen"]}]'::jsonb, (select id from public.knowledge_categories where slug = 'anbau'), 'foundational'::knowledge_difficulty, 'published'::knowledge_status, 8, 3, 'Licht, Ertrag, Terpenprofil und Risikofaktoren im direkten Vergleich – was Forschung und Praxis ueber beide Anbausysteme sagen.', 'de', '2026-03-27'::timestamptz, '{"batch":"wiki_legacy_v1"}'::jsonb) on conflict (slug) do update set title = excluded.title, summary = excluded.summary, body = excluded.body, category_id = excluded.category_id, difficulty = excluded.difficulty, read_minutes = excluded.read_minutes, quality_score = excluded.quality_score;
