insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Muss ich teure Geraete kaufen, um gut anzubauen?', 'Nein. Entscheidend ist die SOP-Konsistenz, nicht die Ausruestung. Guenstige Sensoren mit zuverlaussigem Logging schlagen teure Einzelgeraete.', 0 from public.knowledge_articles where slug = 'cannabis-anbau-grundlagen';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Wie oft sollte ich mich um die Pflanzen kuemmern?', 'Das haengt vom Setup ab. Wichtig ist die Frequenz und Konsistenz: taegliche Beobachtung + woechtliche Messung + monatliche Analyse nach SOP.', 1 from public.knowledge_articles where slug = 'cannabis-anbau-grundlagen';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Gibt es einen Ideal-VPD?', 'Es gibt keinen universellen Idealwert. Je nach Phase (Jungpflanze, Wachstum, Blüte) gelten unterschiedliche Zielbereiche. Konstanz innerhalb des passenden Bereichs ist wichtiger als einzelne Spitzenwerte.', 0 from public.knowledge_articles where slug = 'vpd-einfach-erklaert';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Wie messe ich VPD richtig?', 'Nutze Raumtemperatur, Raumfeuchte und Blatttemperatur per IR-Messung. Eine einfache RH-/Temperatur-Kombination ist nur das Minimum; der Blatt-Offset verbessert die Genauigkeit deutlich.', 1 from public.knowledge_articles where slug = 'vpd-einfach-erklaert';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Welche aw ist sicher?', 'unter 0.65 aw = langzeitstabil; 0.65-0.75 = neutral; ueber 0.75 = Schimmelrisiko. Normen (ISO/AOAC) empfehlen unter 0.70 fuer Cannabis.', 0 from public.knowledge_articles where slug = 'wasseraktivitaet-und-curing';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Wie lange sollte ich curen?', 'Mindestens 2-4 Wochen in Glasbehältern mit 62% RH. Laenger als 8 Wochen bringt minimal Vorzuege, erhoeht aber Schimmelrisiko.', 1 from public.knowledge_articles where slug = 'wasseraktivitaet-und-curing';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Was ist die richtige EC, wenn VPD hoch ist?', 'Wenn der VPD zu hoch und die Luft zu trocken ist, reduzieren Pflanzen oft ihre Wasseraufnahme. Dann sollte die EC nicht vorschnell erhöht werden. Die Reihenfolge lautet: erst Klima stabilisieren, dann die EC feinjustieren.', 0 from public.knowledge_articles where slug = 'vpd-und-ec-kombi-rechner-guide';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Brauche ich teure Sensoren?', 'Nein. Konsistente, kalibrierte günstige Sensoren sind wertvoller als teure unkalibrierte Geräte. Kalibrierung und Datenlogik sind wichtiger als die Geräteklasse.', 1 from public.knowledge_articles where slug = 'vpd-und-ec-kombi-rechner-guide';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Ist Erde oder Coco besser?', 'Nicht pauschal. Erde puffert mehr und verzeiht Einsteigerfehler, Coco reagiert schneller und verlangt saubere Steuerung.', 0 from public.knowledge_articles where slug = 'cannabis-substrat-und-wurzelzone';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Woran erkenne ich ein ueberwaessertes Medium?', 'Topf bleibt lange schwer, Blattbild wirkt traege und die Wurzelzone riecht dumpf oder kippt im Drain.', 1 from public.knowledge_articles where slug = 'cannabis-substrat-und-wurzelzone';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Soll immer Drain entstehen?', 'Nicht bei jeder Wassergabe. Regelmaessige Kontrollgaenge mit Drain sind sinnvoll, staendiges Durchspuelen aber nicht in jedem Setup.', 0 from public.knowledge_articles where slug = 'bewaesserung-ohne-uebergiessen';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Wie schnell darf ein Topf trocknen?', 'Das haengt von Medium und Phase ab. Kritisch wird es, wenn Trocknung ungleichmaessig oder extrem schnell wird und dadurch Salzspitzen entstehen.', 1 from public.knowledge_articles where slug = 'bewaesserung-ohne-uebergiessen';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Brauche ich sofort ein PAR-Meter?', 'Fuer ernsthafte Prozesssteuerung ja, zumindest zeitweise. Schaetzwerte oder App-Messungen reichen nur fuer grobe Orientierung.', 0 from public.knowledge_articles where slug = 'lichtstress-und-canopy-management';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Ist Bleaching immer zu viel Licht?', 'Oft ja, aber nicht nur. Auch Hitze, Naehrstoffungleichgewicht und genetische Empfindlichkeit koennen mit hineinspielen.', 1 from public.knowledge_articles where slug = 'lichtstress-und-canopy-management';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Riecht Schimmel immer muffig?', 'Nicht immer eindeutig. Geruch kann Hinweise liefern, ersetzt aber keine Bewertung ueber Daten und Prozesskontext.', 0 from public.knowledge_articles where slug = 'schimmel-und-mykotoxine-bei-cannabis';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Warum ist aw hier so wichtig?', 'Weil freies Wasser ein zentraler Treiber fuer mikrobielles Wachstum und Produktinstabilitaet ist.', 1 from public.knowledge_articles where slug = 'schimmel-und-mykotoxine-bei-cannabis';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Wie viele KPIs brauche ich?', 'Wenige Kernkennzahlen sind besser als ein ueberladenes Dashboard ohne Entscheidungen.', 0 from public.knowledge_articles where slug = 'grow-log-und-kpi-dashboard';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Reicht ein Spreadsheet?', 'Fuer den Start ja, solange Struktur, Konsistenz und Review-Prozess sauber sind.', 1 from public.knowledge_articles where slug = 'grow-log-und-kpi-dashboard';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Wie oft sollte ich kalibrieren?', 'Abhaengig vom Sensortyp und Einsatzumfeld, aber nie erst dann, wenn Werte offensichtlich unplausibel wirken.', 0 from public.knowledge_articles where slug = 'sensor-kalibrierung-und-messfehler';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Sind billige Sensoren nutzlos?', 'Nein. Gut gefuehrte und gepruefte einfache Sensoren sind oft wertvoller als teure, ungepflegte Systeme.', 1 from public.knowledge_articles where slug = 'sensor-kalibrierung-und-messfehler';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Soll ich im ersten Run toppen, trainieren und boostern?', 'Nur wenn die Basis stabil ist. Fuer den Einstieg ist ein sauberer, einfacher Pflanzenlauf wertvoller als zu viele parallele Eingriffe.', 0 from public.knowledge_articles where slug = 'how-to-grow-cannabis-anfaenger-tutorial';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Was ist fuer Anfaenger wichtiger: EC oder Klima?', 'Klima und Bewaesserung zuerst. Eine Pflanze in schlechtem Klima kann selbst mit sauberem EC nicht stabil performen.', 1 from public.knowledge_articles where slug = 'how-to-grow-cannabis-anfaenger-tutorial';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Wann lohnt sich Coco oder Hydro gegenueber Erde?', 'Wenn dein Mess- und Bewaesserungssystem stabil genug ist, schnellere Reaktionen zu kontrollieren. Ohne Datendisziplin steigt nur die Fehlergeschwindigkeit.', 0 from public.knowledge_articles where slug = 'how-to-grow-cannabis-fortgeschritten-tutorial';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Was bringt mehr: mehr PPFD oder besseres Canopy?', 'Fast immer zuerst besseres Canopy. Ungleich verteiltes Licht macht hohe Leistung ineffizient und steigert Stress in den Spitzen.', 1 from public.knowledge_articles where slug = 'how-to-grow-cannabis-fortgeschritten-tutorial';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Wann wird aus einem guten Grow ein professionelles System?', 'Wenn Ergebnisse ueber mehrere Zyklen, Personen und Zonen reproduzierbar sind und Abweichungen dokumentiert sowie korrigiert werden.', 0 from public.knowledge_articles where slug = 'how-to-grow-cannabis-profi-tutorial';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Was ist auf Profi-Niveau der groesste Engpass?', 'Fast nie nur ein Duenger oder ein Lichtwert, sondern fehlende Standardisierung zwischen Kultur, Hygiene, QA und Postharvest.', 1 from public.knowledge_articles where slug = 'how-to-grow-cannabis-profi-tutorial';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Wie nutze ich den Artikel am besten?', 'Starte mit den Kernpunkten, arbeite die Checkliste durch und vergleiche danach mit deinen aktuellen Prozessen oder Daten.', 0 from public.knowledge_articles where slug = 'naehrstoffblockaden-und-antagonismen';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Ist das ein starres Regelwerk?', 'Nein. Es ist ein strukturierter Rahmen, der je nach Setup angepasst werden sollte, ohne die Datendisziplin zu verlieren.', 1 from public.knowledge_articles where slug = 'naehrstoffblockaden-und-antagonismen';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Wie lange dauert ein verantwortungsvoller Hunt?', 'Mindestens 2 bis 3 Durchläufe. Der erste Hunt identifiziert potenzielle Kandidaten, der zweite prüft Stabilität und Reproduzierbarkeit.', 0 from public.knowledge_articles where slug = 'genetik-und-phaenotyp-selektion';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Was ist das groesste Fehlerrisiko?', 'Unterschiedliche Kulturbedingungen pro Pflanze. Das verfaelscht den Vergleich massiv. Identische Bedingungen sind absolute Pflicht.', 1 from public.knowledge_articles where slug = 'genetik-und-phaenotyp-selektion';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Verliere ich Terpene beim Trocknen und Lagern?', 'Ja, stark. Hitze, Licht und Luftexposition bauen Terpene ab. Kuehle, dunkle, luftdichte Lagerung ist essentiell.', 0 from public.knowledge_articles where slug = 'terpene-und-wirkprofil';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Kann ich Terpenprofile zwischen Chargen vergleichen?', 'Nur, wenn gleiche Analysemethoden, Probenzeiten und Lagerungsbedingungen verwendet wurden. Sonst sind die Vergleiche nicht belastbar.', 1 from public.knowledge_articles where slug = 'terpene-und-wirkprofil';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Warum wirken Edibles spaeter und laenger als Rauchen?', 'Verdauung + Leber-Passage dauern 1-2h. Dafuer wirkt die Wirkung intensiver und persistenter als Inhalation.', 0 from public.knowledge_articles where slug = 'inhalation-vs-edibles';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Kann ich Dosis-Intensitaet zwischen den Methoden vergleichen?', 'Nein direkt. Eine 10mg oral muss nicht eine 10mg inhalativ sein - Bioverfuegbarkeit unterscheidet sich um bis zu 3x.', 1 from public.knowledge_articles where slug = 'inhalation-vs-edibles';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Wie erkenne ich eine gute COA?', 'Pruefe: (1) Lab-Akkreditierung (ISO 17025?), (2) Methoden dokumentiert (GC-MS? HPLC?), (3) Resultat-Unsicherheit angegeben, (4) Signatur des Labor-Direktors.', 0 from public.knowledge_articles where slug = 'coa-richtig-lesen';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Kann eine COA gefaltscht werden?', 'Ja, leicht. Nur Labore mit unabhaengiger Verifizierung (z.B. Proficiency-Tests) sind vertrauenswuerdig.', 1 from public.knowledge_articles where slug = 'coa-richtig-lesen';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Wie erkenne ich PGR-Belaestigung ohne Labor?', 'Normalerweise nicht sicher. Aeusserlich koennen unrealistische Dichten, extreme Feuchte-Verhaeltnisse oder Geruchsverfremdungen Hinweise sein - ersetzen aber keine Analytik.', 0 from public.knowledge_articles where slug = 'pgr-und-kontaminanten';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Welche Kontaminanten sind kritisch?', 'Prioritaet: Pestizide, Pilzgifte und Schwer-Metalle. Dann: Lachgas, PGRs, Loesungsmittelreste. Labore sollten priorisiert nach lokalen Grenzwerten testen.', 1 from public.knowledge_articles where slug = 'pgr-und-kontaminanten';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Reicht Sichtkontrolle ohne Fallen?', 'Meist nicht. Fallen zeigen Trends frueher und helfen, Hotspots vor sichtbaren Schaeden zu finden.', 0 from public.knowledge_articles where slug = 'integrierte-schaedlingspraevention-grow';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Ist jedes Blattproblem gleich ein Schaedling?', 'Nein. Nahrstoffprobleme, Lichtstress oder Umweltstress koennen aehnlich aussehen und muessen sauber abgegrenzt werden.', 1 from public.knowledge_articles where slug = 'integrierte-schaedlingspraevention-grow';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Wie lange kann ich eine Mutterpflanze halten?', 'Technisch lange, aber operativ ist eine geregelte Rotation oft sinnvoller, um Vitalitaet und Hygiene zu sichern.', 0 from public.knowledge_articles where slug = 'mutterpflanzen-und-clone-hygiene';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Brauche ich Backups derselben Linie?', 'Ja. Ein einzelner Ausfall sollte nie die gesamte Genetikstrategie gefaehrden.', 1 from public.knowledge_articles where slug = 'mutterpflanzen-und-clone-hygiene';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Steigt CBN immer nur mit Alter?', 'Alter spielt mit hinein, aber auch Licht, Hitze, Sauerstoff und die Art der Lagerung beeinflussen den Verlauf.', 0 from public.knowledge_articles where slug = 'thc-zu-cbn-abbau-und-oxidation';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Sind alte Produkte automatisch schlecht?', 'Nicht automatisch, aber das Profil kann deutlich von der urspruenglichen Freigabe abweichen. Deshalb ist Lagerkontext entscheidend.', 1 from public.knowledge_articles where slug = 'thc-zu-cbn-abbau-und-oxidation';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Hilft Kuehlung immer?', 'Oft ja, aber nur mit kontrollierter Feuchte und passender Verpackung. Sonst entstehen neue Probleme.', 0 from public.knowledge_articles where slug = 'lagerung-und-terpenverlust-vermeiden';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Warum riecht eine Charge spaeter so anders?', 'Weil Lagerzeit, Licht und Sauerstoffkontakt das Terpenprofil sichtbar veraendern koennen.', 1 from public.knowledge_articles where slug = 'lagerung-und-terpenverlust-vermeiden';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Sind Community-Grade wertlos?', 'Nicht wertlos, aber ohne definierte Kriterien nur begrenzt belastbar.', 0 from public.knowledge_articles where slug = 'bubble-hash-qualitaetskriterien';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Warum ist Trocknung so wichtig?', 'Weil sie Einfluss auf Haltbarkeit, Mikrobiologie und Profilintegritaet hat.', 1 from public.knowledge_articles where slug = 'bubble-hash-qualitaetskriterien';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Ist Rosin immer loesungsmittelfrei?', 'Der Begriff wird so verwendet, aber fuer die Gesamtbewertung bleiben Vorstufe und Prozesskontext trotzdem relevant.', 0 from public.knowledge_articles where slug = 'rosin-einordnung-ohne-hype';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Kann Rosin aus schlechtem Input gut werden?', 'Nur sehr begrenzt. Gute Verarbeitung ersetzt schwaches Ausgangsmaterial nicht.', 1 from public.knowledge_articles where slug = 'rosin-einordnung-ohne-hype';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Ist nicht nachweisbar gleich sicher?', 'Nicht automatisch. Es haengt davon ab, was getestet wurde und wie niedrig die Nachweisgrenze liegt.', 0 from public.knowledge_articles where slug = 'pestizidklassen-und-rueckstandsrisiken';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Warum muss ich die Stoffklasse kennen?', 'Weil unterschiedliche Stoffgruppen verschiedene toxikologische und regulatorische Relevanz haben.', 1 from public.knowledge_articles where slug = 'pestizidklassen-und-rueckstandsrisiken';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Ist Glas immer die beste Verpackung?', 'Nicht automatisch. Schutzwirkung, Headspace, Handling und Lieferkette muessen zusammengedacht werden.', 0 from public.knowledge_articles where slug = 'lagerung-verpackung-und-lichtschutz';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Warum sind Lagerdaten fuer Content relevant?', 'Weil sie erklaeren, warum reale Produktqualitaet von Freigabeprofilen abweichen kann.', 1 from public.knowledge_articles where slug = 'lagerung-verpackung-und-lichtschutz';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Wie nutze ich den Artikel am besten?', 'Starte mit den Kernpunkten, arbeite die Checkliste durch und vergleiche danach mit deinen aktuellen Prozessen oder Daten.', 0 from public.knowledge_articles where slug = 'stressmarker-frueh-erkennen';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Ist das ein starres Regelwerk?', 'Nein. Es ist ein strukturierter Rahmen, der je nach Setup angepasst werden sollte, ohne die Datendisziplin zu verlieren.', 1 from public.knowledge_articles where slug = 'stressmarker-frueh-erkennen';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Wie nutze ich den Artikel am besten?', 'Starte mit den Kernpunkten, arbeite die Checkliste durch und vergleiche danach mit deinen aktuellen Prozessen oder Daten.', 0 from public.knowledge_articles where slug = 'naehrstoffbedarf-cannabis-lebenszyklus';
