insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Ist jeder traditionelle Hash automatisch hochwertig?', 'Nein. Traditionelle Herkunft ist kulturhistorisch relevant, sagt aber ohne Analytik und Prozessnachweise wenig ueber aktuelle Sicherheits- und Qualitaetsniveaus aus.', 0 from public.knowledge_articles where slug = 'hash-typen-vergleichen';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Ist Rosin immer besser als klassischer Presshash?', 'Nicht pauschal. Rosin hat eigene Staerken, aber Endqualitaet bleibt vom Input-Material, der Prozessfuehrung und der Stabilitaet nach Verarbeitung abhaengig.', 1 from public.knowledge_articles where slug = 'hash-typen-vergleichen';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Was ist fuer professionelle Vergleiche am wichtigsten?', 'Eine einheitliche Bewertungsmatrix aus Sensorik, Analytik, Stabilitaet und Chargenkonsistenz statt einzelner Marketingwerte.', 2 from public.knowledge_articles where slug = 'hash-typen-vergleichen';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Sind feminisierte Samen instabil?', 'Nicht automatisch. Gute Linien koennen sehr stabil sein, schlechte Linien zeigen auch als feminisierte Saat Probleme.', 0 from public.knowledge_articles where slug = 'feminisiert-vs-regular-vs-autoflower';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Sind Autoflower immer schneller?', 'Oft im Gesamtablauf, aber nicht in jedem Setup effizienter. Planbarkeit und Zielprofil muessen mitgedacht werden.', 1 from public.knowledge_articles where slug = 'feminisiert-vs-regular-vs-autoflower';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Kann Umwelt das Profil sichtbar veraendern?', 'Ja. Genetik setzt den Rahmen, aber Reife, Stress, Nachernte und Lagerung verschieben das gemessene Ergebnis.', 0 from public.knowledge_articles where slug = 'cannabinoid-biosynthese-verstehen';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Warum schwanken Minor Cannabinoide so stark?', 'Sie liegen oft nahe an Messgrenzen und reagieren empfindlich auf Methode, Reifegrad und Chargenunterschiede.', 1 from public.knowledge_articles where slug = 'cannabinoid-biosynthese-verstehen';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Bestimmt ein Terpen die Wirkung komplett?', 'Nein. Wirkung ist ein Zusammenspiel aus Gesamtprofil, Dosis, Produktform und individueller Reaktion.', 0 from public.knowledge_articles where slug = 'myrcen-limonen-caryophyllen-einordnung';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Warum nutzen Shops diese Begriffe so stark?', 'Weil sie merkfaehig sind. Das macht sie aber nicht automatisch zu belastbaren Wirklabels.', 1 from public.knowledge_articles where slug = 'myrcen-limonen-caryophyllen-einordnung';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Ist Verdampfen automatisch sicher?', 'Nein automatisch nicht. Es kann Belastungsprofile veraendern, aber Geraet, Material und Nutzung bleiben entscheidend.', 0 from public.knowledge_articles where slug = 'vaping-rauchen-und-verdampfen-vergleich';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Warum ist die Temperatur so wichtig?', 'Weil sie Aufnahme, Geschmack, Reizstoffe und Produktverhalten stark beeinflussen kann.', 1 from public.knowledge_articles where slug = 'vaping-rauchen-und-verdampfen-vergleich';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Soll ich solche Begriffe ganz vermeiden?', 'Nein, aber immer erklaeren und nicht als alleinige Qualitaetsaussage stehen lassen.', 0 from public.knowledge_articles where slug = 'full-melt-und-marketingsprache';
insert into public.knowledge_faqs (article_id, question, answer, position) select id, 'Warum ist das fuer grosse Seiten wichtig?', 'Weil unerklaerte Begriffe fuer Einsteiger irrefuehrend sind und Kataloge uneinheitlich machen.', 1 from public.knowledge_articles where slug = 'full-melt-und-marketingsprache';
